window.NexusPages=(()=>{
 const {icon,empty,loading}=NexusUI;
 const projectRows=items=>`<div class="ds-projects">${items.map(p=>`<a class="ds-project-row" href="/builder/${encodeURIComponent(p.id)}"><span class="ds-project-icon">${icon('website')}</span><div><strong>${esc(p.name)}</strong><small>/site/${esc(p.slug)}</small></div><span class="pill ${p.status==='published'?'green':''}">${p.status==='published'?'Published':'Draft'}</span><time>${esc(new Date(p.updatedAt).toLocaleDateString())}</time></a>`).join('')}</div>`;
 function loadProjects(id){queueMicrotask(async()=>{const target=document.getElementById(id);if(!target)return;try{const r=await fetch('/api/website-builder/projects');if(!r.ok)throw Error('Your saved projects could not be loaded.');const items=await r.json();target.innerHTML=items.length?projectRows(items):empty({title:'A place for your next idea',description:'Create a website to start bringing your work together.',kind:'website',action:'<a class="btn" href="/builder">Create a website</a>'});}catch(e){target.innerHTML=empty({title:'Projects are unavailable',description:esc(e.message),kind:'error',action:'<button class="btn" data-action="reload-projects">Try again</button>'});}})}
 function projects(){loadProjects('ds-saved-projects');return head('Projects','Your saved work, ready for its next chapter.','<a class="btn primary" href="/builder">Create project</a>')+`<section class="ds-section"><div class="ds-section-head"><h2>All projects</h2><span>Websites and published pages</span></div><div id="ds-saved-projects">${loading('Loading projects')}</div></section>`;}
 function overview(){loadProjects('ds-recent-projects');return head('A clear view of your work.','Build your presence. Understand your audience. Connect the next step.')+`<section class="ds-welcome"><div><span class="ds-overline">Your workspace</span><h2>What will you build next?</h2><p>Start with a website, then bring your customers and campaigns into the same conversation.</p><a class="btn primary" href="/builder">Create a website</a></div><div class="ds-network" aria-hidden="true"><span>${icon('website',24)}</span><i></i><span class="ds-network-core">${NexusUI.mark()}</span><i></i><span>${icon('crm',24)}</span><small>One connected workspace</small></div></section><div class="ds-quick-grid"><a href="/#campaigns">${icon('campaigns')}<div><h3>Understand your market</h3><p>Review competitor ads and save the evidence.</p></div></a><a href="/#webinars">${icon('webinars')}<div><h3>Bring people together</h3><p>Plan an event and manage registrations.</p></div></a><a href="/#agent">${icon('agent')}<div><h3>Plan your next move</h3><p>Turn a business goal into a reviewable plan.</p></div></a></div><section class="ds-section"><div class="ds-section-head"><h2>Recent projects</h2><a class="link" href="/#projects">View all projects</a></div><div id="ds-recent-projects">${loading('Loading recent work')}</div></section>`;}
 function settings(){return head('Workspace settings','The essentials for a workspace that feels like yours.')+`<section class="ds-settings"><div><h2>Appearance</h2><p>Choose a comfortable view for your work.</p></div><div class="ds-setting-control"><span>${document.body.dataset.theme==='dark'?'Dark':'Light'} appearance</span><button class="btn" data-action="theme-toggle">Change appearance</button></div></section><section class="ds-settings"><div><h2>Connections</h2><p>Manage each service from its workspace.</p></div><div class="ds-setting-links"><a href="/#crm">Customer relationships ${icon('crm')}</a><a href="/#webinars">Calendar and webinars ${icon('webinars')}</a><a href="/#billing">Billing ${icon('billing')}</a></div></section><section class="ds-settings"><div><h2>Website projects</h2><p>Saved drafts and published pages stay separate.</p></div><a class="btn" href="/builder">Manage websites</a></section>`;}
 function workflows(){return head('Workflows','Bring a sequence of work into one considered plan.')+empty({kind:'workflows',title:'Start with the outcome',description:'Use the AI agent to prepare a plan. Automated workflows will appear here when execution is available.',action:'<button class="btn primary" data-page="agent">Prepare a plan</button>'});}
 document.addEventListener('click',e=>{if(e.target.closest('[data-action="reload-projects"]'))renderContent();if(e.target.closest('[data-action="account"]'))modal('Your workspace','<p>You are working in a local Nexus workspace.</p><a class="btn" href="/#settings" data-action="close">Workspace settings</a>');});
 return {overview,projects,settings,workflows,projectRows,loadProjects};
})();
